{"probes": [{"obligation_id": "OB-008", "strategy": "property", "rationale": "For any magnitude that ends up formatted in a unit above B (kB/MB/etc.), the numeric portion must match exactly one digit after the decimal point — never an integer (zero digits) and never two decimals — for both binary and decimal unit systems.", "code": "import re
import impl
from hypothesis import given, strategies as st, settings


@given(n=st.integers(min_value=1001, max_value=10**18), binary=st.booleans())
@settings(max_examples=100)
def test_exactly_one_decimal_digit_above_base_unit(n, binary):
    result = impl.format_bytes(n, binary=binary)
    value_str, unit = result.rsplit(' ', 1)
    if unit != 'B':
        assert re.fullmatch(r'-?\d+\.\d', value_str), (
            f"format_bytes({n!r}, binary={binary!r}) = {result!r} "
            f"does not show exactly one digit after the decimal point"
        )
"}]}
